def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    for idx in range(n - 1, -1, -1):
        a, b, g, k = carpets[idx]
        if a <= x <= a + g and b <= y <= b + k:
            return idx + 1
    return -1

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x][y] = val

    # dp_prev and dp_cur are 2D arrays of size (N+1)x(N+1)
    # Initialize with very small numbers
    NEG_INF = -10**18
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]

    # Step t = 2 corresponds to positions (1,1) for both paths
    dp_prev[1][1] = grid[1][1]

    # Iterate over steps t from 3 to 2N
    for t in range(3, 2 * N + 1):
        # Reset current dp
        for i in range(1, N + 1):
            for j in range(1, N + 1):
                dp_cur[i][j] = NEG_INF

        # x1 and x2 range from max(1, t-N) to min(N, t-1)
        x_min = max(1, t - N)
        x_max = min(N, t - 1)
        for x1 in range(x_min, x_max + 1):
            y1 = t - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(x_min, x_max + 1):
                y2 = t - x2
                if y2 < 1 or y2 > N:
                    continue

                best = NEG_INF
                # Consider all four previous moves
                for dx1 in (0, 1):  # 0: came from left (x1-1), 1: came from up (x1)
                    for dx2 in (0, 1):
                        prev_x1 = x1 - dx1
                        prev_x2 = x2 - dx2
                        if prev_x1 < 1 or prev_x2 < 1:
                            continue
                        prev_y1 = (t - 1) - prev_x1
                        prev_y2 = (t - 1) - prev_x2
                        if prev_y1 < 1 or prev_y1 > N or prev_y2 < 1 or prev_y2 > N:
                            continue
                        val = dp_prev[prev_x1][prev_x2]
                        if val > best:
                            best = val
                if best == NEG_INF:
                    continue

                add = grid[x1][y1]
                if x1 != x2 or y1 != y2:
                    add += grid[x2][y2]
                dp_cur[x1][x2] = best + add

        # Swap dp_prev and dp_cur for next iteration
        dp_prev, dp_cur = dp_cur, dp_prev

    # After final step t = 2N, both paths at (N,N)
    return dp_prev[N][N] if dp_prev[N][N] != NEG_INF else 0

def cantor_numbering(N: int) -> str:
    d = 1
    while d * (d + 1) // 2 < N:
        d += 1
    prev_sum = (d - 1) * d // 2
    offset = N - prev_sum - 1
    if d % 2 == 1:
        numerator = d - offset
        denominator = 1 + offset
    else:
        numerator = 1 + offset
        denominator = d - offset
    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    if K == 0:
        return int(num_str)
    K = min(K, N - 1)

    # Precompute integer values of all substrings
    val = [[0] * N for _ in range(N)]
    for i in range(N):
        num = 0
        for j in range(i, N):
            num = num * 10 + int(num_str[j])
            val[i][j] = num

    # dp[i][k] = maximum product for prefix of length i with k multiplications
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    for i in range(1, N + 1):
        dp[i][0] = val[0][i - 1]

    for k in range(1, K + 1):
        for i in range(k + 1, N + 1):
            best = 0
            for j in range(k, i):
                prod = dp[j][k - 1] * val[j][i - 1]
                if prod > best:
                    best = prod
            dp[i][k] = best

    return dp[N][K]

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    from itertools import combinations
    # Preprocess pairs
    pairs = chatting_pairs
    # Generate all possible aisle positions
    horiz_positions = list(range(1, M))  # between rows
    vert_positions = list(range(1, N))   # between columns
    best_count = -1
    best_horiz = ()
    best_vert = ()
    # If no aisles, just return empty strings
    if K == 0 and L == 0:
        return ('', '')
    # Iterate over combinations
    for h_combo in combinations(horiz_positions, K):
        h_set = set(h_combo)
        for v_combo in combinations(vert_positions, L):
            v_set = set(v_combo)
            count = 0
            for (x1, y1, x2, y2) in pairs:
                separated = False
                # Check horizontal aisle
                if x1 != x2:
                    # find if any aisle between x1 and x2
                    lo, hi = min(x1, x2), max(x1, x2)
                    for r in h_set:
                        if lo <= r < hi:
                            separated = True
                            break
                if not separated and y1 != y2:
                    lo, hi = min(y1, y2), max(y1, y2)
                    for c in v_set:
                        if lo <= c < hi:
                            separated = True
                            break
                if separated:
                    count += 1
            if count > best_count:
                best_count = count
                best_horiz = h_combo
                best_vert = v_combo
    horiz_str = ' '.join(map(str, best_horiz)) if K > 0 else ''
    vert_str = ' '.join(map(str, best_vert)) if L > 0 else ''
    return (horiz_str, vert_str)

def count_passing_ways(n: int, m: int) -> int:
    if m == 0:
        return 1
    dp = [0] * n
    dp[0] = 1
    for _ in range(m):
        new = [0] * n
        for i in range(n):
            left = (i - 1) % n
            right = (i + 1) % n
            new[i] = dp[left] + dp[right]
        dp = new
    return dp[0]

