def max_energy(beads):
    n = len(beads)
    if n <= 1:
        return 0
    arr = beads * 2
    size = 2 * n
    dp = [[0] * size for _ in range(size)]
    for length in range(2, n + 1):
        for i in range(0, size - length + 1):
            j = i + length - 1
            best = 0
            for k in range(i, j):
                val = dp[i][k] + dp[k + 1][j] + arr[i] * arr[k] * arr[j]
                if val > best:
                    best = val
            dp[i][j] = best
    max_val = 0
    for start in range(n):
        end = start + n - 1
        if dp[start][end] > max_val:
            max_val = dp[start][end]
    return max_val

def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        deg = n - i
        if coeff == 0:
            continue
        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)
        # Coefficient part
        if deg == 0:
            coeff_part = str(abs_coeff)
        else:
            coeff_part = '' if abs_coeff == 1 else str(abs_coeff)
        # Variable part
        if deg > 1:
            var_part = f'x^{deg}'
        elif deg == 1:
            var_part = 'x'
        else:
            var_part = ''
        terms.append(f"{sign}{coeff_part}{var_part}")
    return ''.join(terms) if terms else '0'

def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    # Sort applicants by score descending, then registration number ascending
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))
    # Determine the number of applicants to interview (150% of planned recruits, rounded down)
    threshold = int(1.5 * m)
    if threshold <= 0:
        return (0, [])
    # If threshold exceeds the number of applicants, all applicants qualify
    if threshold >= len(sorted_applicants):
        cutoff_score = sorted_applicants[-1][1]
        qualified = sorted_applicants
    else:
        cutoff_score = sorted_applicants[threshold - 1][1]
        qualified = [app for app in sorted_applicants if app[1] >= cutoff_score]
    return (cutoff_score, qualified)

def largest_prime_factor(n: int) -> int:
    """
    Return the larger of the two distinct prime factors of n.
    Assumes n is the product of exactly two distinct primes.
    """
    if n <= 1:
        return n
    i = 2
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 1
    return n

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]
    count = 1  # count the sequence that ends at 'last'
    max_next = last // 2
    for next_val in range(1, max_next + 1):
        count += count_sequences(n, next_val, memo)
    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    if y0 % x0 != 0:
        return 0
    n = y0 // x0
    count = 0
    a = 1
    while a * a <= n:
        if n % a == 0:
            b = n // a
            if math.gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        a += 1
    return count

def string_transformation(A: str, B: str, rules: list) -> int | str:
    if A == B:
        return 0
    queue = [(A, 0)]
    visited = {A}
    while queue:
        current, steps = queue.pop(0)
        if steps >= 10:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1
    return "NO ANSWER!"

def find_min_n_greater_than_k(k: int) -> int:
    import math
    if k <= 0:
        return 1
    gamma = 0.57721566490153286060651209
    n_est = int(math.exp(k - gamma))
    if n_est < 1:
        n_est = 1
    s = 0.0
    for i in range(1, n_est + 1):
        s += 1.0 / i
    while n_est > 1 and s - 1.0 / n_est > k:
        s -= 1.0 / n_est
        n_est -= 1
    while s <= k:
        n_est += 1
        s += 1.0 / n_est
    return n_est

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    s = str(n)
    mapping = {}
    for x, y in rules:
        mapping.setdefault(str(x), []).append(str(y))
    visited = {n}
    queue = [s]
    while queue:
        cur = queue.pop(0)
        for i, ch in enumerate(cur):
            if ch in mapping:
                for rep in mapping[ch]:
                    new = cur[:i] + rep + cur[i+1:]
                    new_int = int(new)
                    if new_int not in visited:
                        visited.add(new_int)
                        queue.append(new)
    return len(visited)

def calculate_score(system: int, points: str) -> list:
    scores = []
    player = 0
    opponent = 0
    for p in points:
        if p == 'W':
            player += 1
        elif p == 'L':
            opponent += 1
        else:
            continue  # ignore invalid characters
        # Check if game finished
        if (player >= system or opponent >= system) and abs(player - opponent) >= 2:
            scores.append(f"{player}:{opponent}")
            player = 0
            opponent = 0
    # If there is an unfinished game, add its current score
    if player != 0 or opponent != 0:
        scores.append(f"{player}:{opponent}")
    return scores

